-- Upsert 33 social missions (fixed UUIDs). Deactivate legacy social seed rows.
-- Source: docs/missions.seed.json

on conflict (id) do update set
  category = excluded.category,
  teaser = excluded.teaser,
  title = excluded.title,
  body = excluded.body,
  locale = excluded.locale,
  is_active = excluded.is_active;

update public.missions
set is_active = false
where id in (
  'a1f2e3d4-c5b6-4789-a012-345678901101'::uuid,
  'a1f2e3d4-c5b6-4789-a012-345678901102'::uuid
);
